const departments=[['Partnership','◇'],['Marketing','✦'],['Lab','◎']];
const leads={Partnership:'Nahi Nguyen',Marketing:'Giatri Drajat',Lab:'Sakurako Esaka'};
const president='Kuei Maesaka';
const state={departments:[],date:0,slot:null,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Tokyo'};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const grid=$('#deptGrid');
const staff=[['Kuei Maesaka','President'],['Nahi Nguyen','Partnership Lead'],['Giatri Drajat','Marketing Lead'],['Sakurako Esaka','Lab Lead']];
departments.forEach(([name,icon])=>{const b=document.createElement('button');b.type='button';b.className='dept';b.dataset.name=name;b.innerHTML=`<i>${icon}</i><span>${name}</span><span class="rank">+</span>`;b.onclick=()=>toggleDept(name);grid.appendChild(b)});
staff.forEach(([name,role])=>{const b=document.createElement('button');b.className='staff-card';b.innerHTML=`<span>${name.split(' ').map(n=>n[0]).join('')}</span><div><strong>${name}</strong><small>${role}</small></div><i>→</i>`;b.onclick=()=>{document.querySelectorAll('.staff-card').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');localStorage.setItem('jvaStaffProfile',name)};$('#staffList').appendChild(b)});
function toggleDept(name){const i=state.departments.indexOf(name);if(i>=0)state.departments.splice(i,1);else if(state.departments.length<3)state.departments.push(name);$$('.dept').forEach(b=>{const n=state.departments.indexOf(b.dataset.name);b.classList.toggle('selected',n>=0);b.querySelector('.rank').textContent=n>=0?n+1:'+'});$('#selection p').textContent=state.departments.length?state.departments.join('  →  '):'No departments selected yet'}
const switchScreen=id=>{['intro','roleChoice','staffPortal','scheduler'].forEach(v=>$('#'+v).classList.toggle('hidden',v!==id));scrollTo(0,0)};
$('#startBtn').onclick=()=>switchScreen('roleChoice');
$('#backIntro').onclick=()=>switchScreen('intro');
$('#applicantRole').onclick=()=>switchScreen('scheduler');
$('#staffRole').onclick=()=>switchScreen('staffPortal');
$('#backRoles').onclick=()=>switchScreen('roleChoice');
$('#backHome').onclick=()=>switchScreen('roleChoice');
const dates=Array.from({length:7},(_,i)=>new Date(2026,9,19+i));
function renderDates(){const el=$('#dateStrip');el.innerHTML='';dates.forEach((d,i)=>{const b=document.createElement('button');b.className='date-btn '+(i===state.date?'active':'');b.innerHTML=`<small>${d.toLocaleDateString('en',{weekday:'short'}).toUpperCase()}</small><b>${d.getDate()}</b><small>${d.toLocaleDateString('en',{month:'short'}).toUpperCase()}</small>`;b.onclick=()=>{state.date=i;renderDates();renderSlots()};el.appendChild(b)})}
function renderSlots(){const times=['09:00','09:45','10:30','11:15','13:00','13:45','14:30','15:15','16:00','16:45'];const el=$('#slots');el.innerHTML='';times.filter((_,i)=>(i+state.date)%4!==0).forEach(t=>{const b=document.createElement('button');b.className='slot';const [h,m]=t.split(':');const d=new Date(dates[state.date]);d.setHours(+h,+m);b.textContent=d.toLocaleTimeString('en',{hour:'numeric',minute:'2-digit'});b.onclick=()=>chooseSlot(d);el.appendChild(b)})}
const tzs=[state.timezone,'Asia/Tokyo','America/New_York','America/Los_Angeles','Europe/London','Europe/Paris'].filter((v,i,a)=>a.indexOf(v)===i);tzs.forEach(t=>$('#timezoneSelect').add(new Option(t.replaceAll('_',' '),t)));$('#timezoneSelect').value=state.timezone;$('#timezoneLabel').textContent=state.timezone.replaceAll('_',' ');$('#timezoneSelect').onchange=e=>{state.timezone=e.target.value;$('#timezoneLabel').textContent=state.timezone.replaceAll('_',' ');renderSlots()};
function showView(id,step){['detailsForm','timeView','confirmView','successView'].forEach(v=>$('#'+v).classList.toggle('hidden',v!==id));$$('.steps li').forEach((li,i)=>li.classList.toggle('active',i===step));scrollTo(0,0)}
$('#detailsForm').onsubmit=e=>{e.preventDefault();if(!state.departments.length){$('#selection').animate([{transform:'translateX(-5px)'},{transform:'translateX(5px)'},{transform:'none'}],{duration:250});return}const lead=leads[state.departments[0]];$('#panelNames').textContent=`${lead} · ${president} may join`;$('#leadInitials').textContent=lead.split(' ').map(n=>n[0]).join('');renderDates();renderSlots();showView('timeView',1)};
function chooseSlot(date){state.slot=date;const fmt={weekday:'long',month:'long',day:'numeric',hour:'numeric',minute:'2-digit'};$('#summaryDay').textContent=date.getDate();$('#summaryMonth').textContent=date.toLocaleDateString('en',{month:'short'}).toUpperCase();$('#summaryTime').textContent=date.toLocaleString('en',fmt);$('#reviewName').textContent=$('#firstName').value+' '+$('#lastName').value;$('#reviewEmail').textContent=$('#email').value;$('#reviewDept').textContent=state.departments.join(' → ');$('#reviewPanel').textContent=`${leads[state.departments[0]]} (required); ${president} (optional)`;showView('confirmView',2)}
$('#backDetails').onclick=()=>showView('detailsForm',0);$('#backTimes').onclick=()=>showView('timeView',1);
$('#confirmBtn').onclick=()=>{const btn=$('#confirmBtn');btn.textContent='Saving preview…';btn.disabled=true;setTimeout(()=>{const pretty=state.slot.toLocaleString('en',{weekday:'long',month:'long',day:'numeric',hour:'numeric',minute:'2-digit'});$('#successDate').textContent=pretty;$('#successCopy').textContent=`Thanks, ${$('#firstName').value}. This test booking is stored only in this browser. Nothing was emailed to ${$('#email').value}.`;showView('successView',2);btn.innerHTML='Save test booking <span>✓</span>';btn.disabled=false;localStorage.setItem('jvaBooking',JSON.stringify({...state,email:$('#email').value,name:$('#firstName').value}))},750)};
$('#addCalendar').onclick=()=>{if(!state.slot)return;const end=new Date(state.slot.getTime()+45*60000);const f=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const url=`https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent('JVA Core Team Interview')}&dates=${f(state.slot)}/${f(end)}&details=${encodeURIComponent('45 minutes reserved: 30-minute interview plus 15-minute buffer. Preview booking; organizer has not yet created a Google Meet link.')}`;window.open(url,'_blank')};
$('#reschedule').onclick=()=>showView('timeView',1);
